+
+export async function rateLimit(req: FastifyRequest, reply: FastifyReply) {
+  const key = (req.headers['x-forwarded-for'] as string) ?? req.ip;
+  const now = Date.now();
+  const bucket = buckets.get(key) ?? { tokens: config.rateLimitBurst, updatedAt: now };
